<template>
  <section class="changes">
    <header class="head"><div><small>CHANGE CONTROL</small><h2>修改记录</h2><p>每条记录来自真实扫描页面和 AI 候选，审核、导出状态由服务端自动更新。</p></div><el-button :loading="loading" @click="load"><i class="fas fa-refresh"/> 刷新</el-button></header>
    <div class="status-board"><article v-for="item in counters" :key="item.key"><i :class="item.icon"/><div><span>{{item.label}}</span><b>{{item.value}}</b></div></article></div>
    <div class="toolbar"><el-select v-model="filter" clearable placeholder="全部状态"><el-option v-for="(label,key) in statusText" :key="key" :label="label" :value="key"/></el-select><span>共 {{visibleRows.length}} 条真实记录</span></div>
    <el-table :data="visibleRows" v-loading="loading" stripe>
      <el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusText[row.status]||row.status}}</el-tag></template></el-table-column>
      <el-table-column label="页面与站点" min-width="230"><template #default="{row}"><b>{{row.site_name}}</b><a :href="row.url" target="_blank" rel="noopener">{{row.url}}</a></template></el-table-column>
      <el-table-column label="修改内容" min-width="330"><template #default="{row}"><div class="diff"><del>{{row.original_title||'原页面未设置标题'}}</del><ins>{{row.candidate_title}}</ins><small>{{row.rationale||'基于页面扫描事实生成'}}</small></div></template></el-table-column>
      <el-table-column prop="model_code" label="执行模型" width="130"/><el-table-column prop="created_at" label="创建时间" width="170"/><el-table-column label="完成时间" width="170"><template #default="{row}">{{row.exported_at||row.approved_at||'--'}}</template></el-table-column>
      <el-table-column label="操作" width="180"><template #default="{row}"><el-button v-if="row.status==='draft'" link type="primary" @click="review(row,'approved')">批准</el-button><el-button v-if="row.status==='draft'" link type="danger" @click="review(row,'rejected')">拒绝</el-button><el-button v-if="['approved','exported'].includes(row.status)" link type="primary" @click="exportItem(row)">{{row.status==='exported'?'再次下载':'导出并完成'}}</el-button></template></el-table-column>
    </el-table>
    <el-empty v-if="!loading&&!visibleRows.length" description="暂无符合条件的真实修改记录"/>
  </section>
</template>
<script setup>
import{computed,onMounted,ref}from'vue';import api from'@/api';import{ElMessage}from'element-plus';
const rows=ref([]),loading=ref(false),filter=ref(''),statusText={draft:'待审核',approved:'已批准',rejected:'已拒绝',exported:'已导出'},visibleRows=computed(()=>filter.value?rows.value.filter(r=>r.status===filter.value):rows.value),counters=computed(()=>[{key:'all',label:'全部修改',value:rows.value.length,icon:'fas fa-code-branch'},{key:'draft',label:'待审核',value:rows.value.filter(r=>r.status==='draft').length,icon:'fas fa-hourglass-half'},{key:'approved',label:'已批准',value:rows.value.filter(r=>r.status==='approved').length,icon:'fas fa-check-circle'},{key:'exported',label:'已完成',value:rows.value.filter(r=>r.status==='exported').length,icon:'fas fa-cloud-arrow-up'}]);
async function load(){loading.value=true;try{const r=await api.get('/user/seo/candidates');rows.value=r.data?.data||r.data||[]}finally{loading.value=false}}
async function review(row,status){await api.put(`/user/seo/candidates/${row.id}/review`,{status});ElMessage.success(status==='approved'?'已批准，记录状态已更新':'已拒绝，记录状态已更新');await load()}
async function exportItem(row){const r=await api.post(`/user/seo/candidates/${row.id}/export`);const blob=new Blob([JSON.stringify(r.data?.data||r.data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`seo-change-${row.id}.json`;a.click();URL.revokeObjectURL(a.href);ElMessage.success('已导出，关联任务状态已自动完成');await load()}
const statusType=s=>({draft:'warning',approved:'success',rejected:'danger',exported:'info'}[s]||'info');onMounted(load)
</script>
<style scoped>.changes{max-width:1180px;margin:auto}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.head small{color:#7c3aed;font-weight:700}.head h2{font-size:24px;margin:5px 0}.head p{margin:0;color:#667085}.status-board{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.status-board article{display:flex;align-items:center;gap:12px;background:#fff;border:1px solid #e4e8ee;border-radius:7px;padding:15px}.status-board i{width:34px;height:34px;display:grid;place-items:center;background:#f3efff;color:#7c3aed;border-radius:6px}.status-board span,.toolbar{font-size:12px;color:#667085}.status-board b{display:block;font-size:20px}.toolbar{display:flex;align-items:center;gap:12px;margin-bottom:12px}.toolbar .el-select{width:150px}a{display:block;color:#667085;font-size:11px;margin-top:4px}.diff{display:grid;gap:5px}.diff del{color:#b42318;font-size:11px}.diff ins{color:#067647;text-decoration:none;font-weight:600}.diff small{color:#667085}@media(max-width:700px){.head p{display:none}.status-board{grid-template-columns:1fr 1fr}}</style>
